import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));

// backend/src/middleware -> backend/public/404.html (generated by the Next.js
// static export and copied in by `npm run build:frontend`).
const notFoundPagePath = path.resolve(__dirname, "../../public/404.html");

export function notFound(req, res) {
  // API calls and non-GET requests always get JSON, never the frontend HTML.
  if (
    req.path === "/api" ||
    req.path.startsWith("/api/") ||
    !["GET", "HEAD"].includes(req.method)
  ) {
    return res.status(404).json({ error: "Route not found" });
  }

  // Missing build artifacts (JS/CSS/images) must not return the HTML page:
  // the browser would try to parse it as the requested asset type.
  if (req.path.startsWith("/_next/") || path.extname(req.path) !== "") {
    return res.status(404).type("text/plain").send("Not found");
  }

  // Unknown frontend route: serve the Next.js exported 404 page when present.
  if (fs.existsSync(notFoundPagePath)) {
    return res.status(404).sendFile(notFoundPagePath);
  }

  return res.status(404).json({ error: "Route not found" });
}

export function errorHandler(err, req, res, next) {
  // Structured errors thrown by services (HttpError or anything with a
  // numeric statusCode). `code` + `details` are echoed when present; the
  // stack is never sent to the client.
  if (typeof err?.statusCode === "number") {
    const body = { error: err.message };
    if (err.code) body.code = err.code;
    if (err.details) body.details = err.details;
    if (process.env.NODE_ENV !== "production") {
      console.error(`[${err.statusCode}] ${err.message}`, err.code ?? "");
    }
    return res.status(err.statusCode).json(body);
  }
  console.error(err);
  if (err?.name === "ZodError") {
    return res.status(400).json({ error: "Validation failed", details: err.issues });
  }
  if (err?.code === "P2002") {
    return res.status(409).json({ error: "A record with this value already exists" });
  }
  if (err?.code === "P2025") {
    return res.status(404).json({ error: "Record not found" });
  }
  res.status(500).json({ error: "Internal server error" });
}
